frappe.ui.form.on('Employee', {
    ctc: function(frm) {
        if (frm.doc.ctc) {

            let custom_gross_pay_amount = (frm.doc.ctc)/12;
            let custom_base_pay_amount = (custom_gross_pay_amount)* 0.5;
            let custom_hra = (custom_base_pay_amount)* 0.40
            frm.set_value('custom_gross_pay_amount', custom_gross_pay_amount);
            frm.set_value('custom_base_pay_amount', custom_base_pay_amount);
            frm.set_value('custom_hra', custom_hra);


        }
    }
});

frappe.ui.form.on('Customer', {
    after_save: function(frm) {

        // Fetch Address linked to this customer
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Address",
                filters: {
                    link_name: frm.doc.name
                },
                fields: ["address_line1","city","state","country","pincode"],
                limit_page_length: 1
            },
            callback: function(r) {
                if (r.message.length > 0) {
                    let addr = r.message[0];

                    frm.set_value(
                        "custom_customer_address",
                        addr.address_line1 + ", " +
                        addr.city + ", " +
                        addr.state + ", " +
                        addr.country + " - " +
                        addr.pincode
                    );
                }
            }
        });

