frappe.ui.form.on('Brick Production', {
    brick_size(frm) {

        // 🔹 If NO brick size selected → Clear table & return
        if (!frm.doc.brick_size) {
            frm.clear_table("raw_materials");
            frm.refresh_field("raw_materials");

            // Also clear batch quantity & produced bricks if you want
            frm.set_value("batch_quantity", "");
            frm.set_value("produced_bricks", 0);

            return;
        }

        // 🔹 Clear Raw Materials Table before loading new BOM
        frm.clear_table("raw_materials");
        frm.refresh_field("raw_materials");

        // 🔹 Fetch Default BOM linked to Brick Size
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "BOM",
                filters: {
                    item: frm.doc.brick_size,
                    is_default: 1
                },
                fields: ["name"]
            },
            callback: function(r) {

                if (!r.message || r.message.length === 0) {
                    frappe.msgprint("No Default BOM found for this Brick Size");
                    return;
                }

                let bom_name = r.message[0].name;

                // 🔹 Fetch BOM Details
                frappe.call({
                    method: "frappe.client.get",
                    args: {
                        doctype: "BOM",
                        name: bom_name
                    },
                    callback: function(res) {
                        let bom = res.message;
                        if (!bom) return;

                        // 🔹 Set Batch Quantity from BOM
                        frm.set_value("batch_quantity", bom.quantity);

                        // 🔹 Add Raw Materials from BOM Items
                        if (bom.items && bom.items.length > 0) {
                            bom.items.forEach(item => {
                                let row = frm.add_child("raw_materials");
                                row.item_code = item.item_code;
                                row.quantity = item.qty;

                                row.uom = item.uom;
                                row.rate = item.rate;
                                row.amount = item.amount;
                            });

                            frm.refresh_field("raw_materials");
                        }
                    }
                });
            }
        });
    }
});

