frappe.ui.form.on("Brick Production", {

    refresh(frm) {
        calculate_totals(frm);
    },

    no_of_batches(frm) {
        calculate_produced(frm);
    },

    batch_quantity(frm) {
        calculate_produced(frm);
    },

    raw_materials_add(frm) {
        calculate_totals(frm);
    },

    raw_materials_remove(frm) {
        calculate_totals(frm);
    }

});


frappe.ui.form.on("Bricks", {

    quantity(frm, cdt, cdn) {
        calculate_row(frm, cdt, cdn);
    },

    rate(frm, cdt, cdn) {
        calculate_row(frm, cdt, cdn);
    }

});


function calculate_row(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    row.amount = flt(row.quantity) * flt(row.rate);

    frm.refresh_field("raw_materials");

    calculate_totals(frm);
}


function calculate_produced(frm) {

    frm.set_value(
        "produced_bricks",
        flt(frm.doc.no_of_batches) * flt(frm.doc.batch_quantity)
    );

    calculate_totals(frm);
}


function calculate_totals(frm) {

    let total = 0;

    (frm.doc.raw_materials || []).forEach(function(row) {

        // This ensures even old rows are recalculated
        row.amount = flt(row.quantity) * flt(row.rate);

        total += flt(row.amount);
    });

    frm.refresh_field("raw_materials");

    frm.set_value("total_production_cost", total);

    frm.set_value(
        "brick_cost",
        flt(frm.doc.produced_bricks)
            ? total / flt(frm.doc.produced_bricks)
            : 0
    );

    frm.set_value(
        "batch_cost",
        flt(frm.doc.no_of_batches)
            ? total / flt(frm.doc.no_of_batches)
            : 0
    );
}

frappe.ui.form.on('Brick Production', {

    brick_size(frm) {

        if (!frm.doc.brick_size) {
            frm.clear_table("raw_materials");
            frm.refresh_field("raw_materials");
            frm.set_value("batch_quantity", "");
            frm.set_value("produced_bricks", 0);
            frm.set_value("total_production_cost", 0);
            return;
        }

        frm.clear_table("raw_materials");
        frm.refresh_field("raw_materials");

        // Fetch default BOM
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "BOM",
                filters: {
                    item: frm.doc.brick_size,
                    is_default: 1
                },
                fields: ["name"]
            },
            callback: function(r) {

                if (!r.message || r.message.length === 0) {
                    frappe.msgprint("No Default BOM found for this Brick Size");
                    return;
                }

                let bom_name = r.message[0].name;

                frappe.call({
                    method: "frappe.client.get",
                    args: { doctype: "BOM", name: bom_name },
                    callback: function(res) {
                        let bom = res.message;
                        if (!bom) return;

                        frm.set_value("batch_quantity", bom.quantity);

                        if (bom.items && bom.items.length > 0) {
                            bom.items.forEach(item => {
                                let row = frm.add_child("raw_materials");
                                row.item_code = item.item_code;
                                row.quantity = item.qty;
                                row.uom = item.uom;
                                row.rate = item.rate;
                                row.amount = item.amount;
                            });

                            frm.refresh_field("raw_materials");

                            // 🔥 NEW — Calculate total immediately after loading BOM
                            frm.events.calculate_total_cost(frm);
                        }
                    }
                });
            }
        });
    },

    // Reusable total calculation function
    calculate_total_cost(frm) {
        let total = 0;

        (frm.doc.raw_materials || []).forEach(row => {
            total += row.amount || 0;
        });

        frm.set_value("total_production_cost", total);
    },

    no_of_batches(frm) {
        frm.events.calculate_total_cost(frm);
    }
});


// Child Table triggers
frappe.ui.form.on('Brick Production Raw Materials', {

    amount(frm) {
        frm.events.calculate_total_cost(frm);
    },

    quantity(frm) {
        frm.events.calculate_total_cost(frm);
    },

    rate(frm) {
        frm.events.calculate_total_cost(frm);
    }
});

// ---------------------------------------------------------
// Utility: Recalculate Produced Bricks
// ---------------------------------------------------------
function calculate_produced(frm) {
    let batches = cint(frm.doc.no_of_batches) || 0;
    let qty = flt(frm.doc.batch_quantity) || 0;
    frm.set_value("produced_bricks", batches * qty);
}

// ---------------------------------------------------------
// Utility: Recalculate Total, Batch Cost & Brick Cost
// ---------------------------------------------------------
function calculate_total_cost(frm) {
    let total = 0;

    (frm.doc.raw_materials || []).forEach(row => {
        total += flt(row.amount) || 0;
    });

    frm.set_value("total_production_cost", total);

    let batches = cint(frm.doc.no_of_batches) || 0;
    frm.set_value("batch_cost", batches > 0 ? total / batches : 0);

    let produced = cint(frm.doc.produced_bricks) || 0;
    frm.set_value("brick_cost", produced > 0 ? total / produced : 0);
}

// ---------------------------------------------------------
// Update Materials when No. of Batches changes
// ---------------------------------------------------------
function update_batch_quantities(frm) {
    let batches = cint(frm.doc.no_of_batches) || 0;

    // Save base quantity first time only
    (frm.doc.raw_materials || []).forEach(row => {
        if (row.quantity_original == null || row.quantity_original === undefined) {
            row.quantity_original = row.quantity;
        }
    });

    if (!batches || batches <= 0) {
        // Restore original quantities
        (frm.doc.raw_materials || []).forEach(row => {
            row.quantity = row.quantity_original || 0;
            row.amount = flt(row.rate) * flt(row.quantity);
        });

        frm.refresh_field("raw_materials");
        calculate_produced(frm);
        calculate_total_cost(frm);
        return;
    }

    // Multiply from base quantity ALWAYS
    (frm.doc.raw_materials || []).forEach(row => {
        row.quantity = flt(row.quantity_original) * batches;
        row.amount = flt(row.rate) * flt(row.quantity);
    });

    frm.refresh_field("raw_materials");
    calculate_produced(frm);
    calculate_total_cost(frm);
}

// ---------------------------------------------------------
// Fetch BOM materials when Brick Size changes
// ---------------------------------------------------------
frappe.ui.form.on("Brick Production", {
    brick_size(frm) {
        if (!frm.doc.brick_size) {
            frm.clear_table("raw_materials");
            frm.refresh_field("raw_materials");
            frm.set_value("batch_quantity", "");
            frm.set_value("produced_bricks", 0);
            frm.set_value("total_production_cost", 0);
            return;
        }

        frm.clear_table("raw_materials");
        frm.refresh_field("raw_materials");

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "BOM",
                filters: { item: frm.doc.brick_size, is_default: 1 },
                fields: ["name"]
            },
            callback: function(r) {
                if (!r.message || r.message.length === 0) {
                    frappe.msgprint("No Default BOM found for this Brick Size");
                    return;
                }

                let bom_name = r.message[0].name;

                frappe.call({
                    method: "frappe.client.get",
                    args: { doctype: "BOM", name: bom_name },
                    callback: function(res) {
                        let bom = res.message;
                        if (!bom) return;

                        frm.set_value("batch_quantity", bom.quantity);

                        (bom.items || []).forEach(item => {
                            let row = frm.add_child("raw_materials");
                            row.item_code = item.item_code;
                            row.quantity = item.qty;
                            row.quantity_original = item.qty;  // Base qty saved here
                            row.uom = item.uom;
                            row.rate = item.rate;
                            row.amount = item.amount;
                        });

                        frm.refresh_field("raw_materials");
                        calculate_total_cost(frm);
                    }
                });
            }
        });
    },

    // When No. of Batches changes → Update calculations all-in-one
    no_of_batches(frm) {
        update_batch_quantities(frm);
    },

    // When Produced Bricks changes → Recalculate costs
    produced_bricks(frm) {
        calculate_total_cost(frm);
    },

    // Auto update when form loads
    refresh(frm) {
        calculate_total_cost(frm);
    }
});

// ---------------------------------------------------------
// Child Table Cost Triggers
// ---------------------------------------------------------
frappe.ui.form.on("Brick Production Raw Materials", {
    quantity(frm) {
        calculate_total_cost(frm);
    },
    rate(frm) {
        calculate_total_cost(frm);
    },
    amount(frm) {
        calculate_total_cost(frm);
    }
});



