frappe.listview_settings['Sales Invoice'] = {
    onload: function(listview) {

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Sales Invoice",
                filters: [
                    ["docstatus", "=", 1],
                    ["status", "!=", "Paid"],
                    ["due_date", ">=", frappe.datetime.get_today()],
                    ["due_date", "<=", frappe.datetime.add_days(frappe.datetime.get_today(), 3)]
                ],
                fields: ["name", "customer", "due_date"]
            },

            callback: function(r) {

                if (r.message && r.message.length > 0) {

                    let msg = "";

                    r.message.forEach(inv => {
                        msg += `
                            <p>
                                <b>${inv.name}</b> - 
                                ${inv.customer} - 
                                Due: ${inv.due_date}
                            </p>
                        `;
                    });

                    frappe.msgprint({
                        title: __('Upcoming Due Invoices'),
                        message: msg,
                        indicator: 'orange'
                    });
                }
            }
        });

    }
};

frappe.ui.form.on("Quotation", {

    custom_quotation_type(frm) {

        // Update all existing rows
        (frm.doc.items || []).forEach(row => {

            frappe.model.set_value(
                row.doctype,
                row.name,
                "custom_quotation_type",
                frm.doc.custom_quotation_type
            );

        });

        frm.refresh_field("items");
    }

});

frappe.ui.form.on("Quotation Item", {

    items_add(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        row.custom_quotation_type =
            frm.doc.custom_quotation_type;

        frm.refresh_field("items");

    }

});

frappe.ui.form.on("Quotation", {

    custom_quotation_type(frm) {

        (frm.doc.items || []).forEach(row => {

            // sync parent value to child
            row.custom_quotation_type =
                frm.doc.custom_quotation_type;

            // clear quantity
            if (frm.doc.custom_quotation_type === "Brick Quote") {
                row.qty = "1";
            }

        });

        frm.refresh_field("items");

    }

});

frappe.ui.form.on("Quotation Item", {

    item_code: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row.item_code) return;

        frappe.db.get_doc("Item", row.item_code)
            .then(item => {

                let uoms = [];

                (item.uoms || []).forEach(r => {
                    uoms.push(r.uom);
                });

                // Apply filter
                frm.fields_dict.items.grid
                    .get_field("uom")
                    .get_query = function() {

                        return {
                            filters: [
                                ["UOM", "name", "in", uoms]
                            ]
                        };

                    };

                frm.refresh_field("items");

            });

    }

});

frappe.ui.form.on("Block Price Template", {

    refresh(frm) {
        update_total_item(frm);
    },

    block_category(frm) {

        // Filter child items
        frm.set_query("item", "items", function () {

            return {
                filters: {
                    item_group: frm.doc.block_category
                }
            };

        });

    }

});


