    gst(frm, cdt, cdn) {
        calculate_gst(frm, cdt, cdn);
    },

    rate(frm, cdt, cdn) {
        calculate_gst(frm, cdt, cdn);
    }

});


function update_total_item(frm) {

    frm.set_value(
        "total_item",
        (frm.doc.items || []).length
    );

}


