function calculate_gst(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    if (!row.rate || !row.gst)
        return;

    frappe.db.get_doc(
        "Item Tax Template",
        row.gst
    ).then(doc => {

        let gst_rate = 0;

        if (
            doc.taxes &&
            doc.taxes.length
        ) {

            gst_rate =
                doc.taxes[0].tax_rate || 0;

        }

        let total =
            flt(row.rate) +
            (
                flt(row.rate)
                *
                flt(gst_rate)
                / 100
            );

        frappe.model.set_value(
            cdt,
            cdn,
            "block_cost_with_gst",
            total
        );

    });

}

