function calculate_due_date(frm) {

    // Immediately
    if (frm.doc.custom_payment_terms == "Immediately") {

        // Clear custom days
        frm.set_value("custom_days", "");

        // Due date = Posting Date
        if (frm.doc.posting_date) {
            frm.set_value("due_date", frm.doc.posting_date);
        }

    }

    // Days
    else if (frm.doc.custom_payment_terms == "Days") {

        // Clear previous Due Date first
        frm.set_value("due_date", "");

        if (frm.doc.custom_days > 0 && frm.doc.posting_date) {

            let due_date = frappe.datetime.add_days(
                frm.doc.posting_date,
                cint(frm.doc.custom_days)
            );

            frm.set_value("due_date", due_date);
        }

    }

    // If payment terms is empty/changed to something else
    else {

        frm.set_value("custom_days", "");
        frm.set_value("due_date", "");
    }
}

