                        let total_qty = frm.doc.total_qty || 0;
                        let total = frm.doc.base_total || frm.doc.total || 0; 
                        let taxes = frm.doc.base_total_taxes_and_charges || 0;
                        let grand_total = frm.doc.base_grand_total || 0;

                        // Build the message
                        let message = `*NEW QUOTATION*\n=========================\n`;
                        message += `*From:* ${company}\n*To:* ${customer}\n*Quotation ID:* ${frm.doc.name}\n`;
