frappe.ui.form.on("Brick Production", {
    brick_type: function(frm) {

        if (!frm.doc.brick_type) {
            frm.clear_table("raw_materials");
            frm.refresh_field("raw_materials");
            return;
        }

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Brick BOM",
                filters: {
                    brick_category: frm.doc.brick_type
                },
                fields: ["name"],
                limit_page_length: 1
            },
            callback: function(r) {

                if (!r.message || !r.message.length) {
                    frappe.msgprint("No Brick BOM found for the selected Brick Type.");
                    frm.clear_table("raw_materials");
                    frm.refresh_field("raw_materials");
                    return;
                }

                let bom = r.message[0].name;

                frappe.call({
                    method: "frappe.client.get",
                    args: {
                        doctype: "Brick BOM",
                        name: bom
                    },
                    callback: function(res) {

                        frm.clear_table("raw_materials");

                        (res.message.raw_materials || []).forEach(function(d) {

                            let row = frm.add_child("raw_materials");

                            row.item_code = d.item;
                            row.uom = d.uom;

                        });

                        frm.refresh_field("raw_materials");
                    }
                });

            }
        });

    }
});

