frappe.ui.form.on("Address", {

    pincode: function(frm) {

        let pincode = (frm.doc.pincode || "").trim();

        if (!pincode) {
            frm.set_value("city", "");
            frm.set_value("state", "");
            return;
        }

        if (!/^\d{6}$/.test(pincode)) {
            return;
        }

        fetch("https://api.postalpincode.in/pincode/" + pincode)
            .then(response => response.json())
            .then(data => {

                if (
                    data &&
                    data[0] &&
                    data[0].Status === "Success" &&
                    data[0].PostOffice &&
                    data[0].PostOffice.length
                ) {

                    let post = data[0].PostOffice[0];

                    frm.set_value("city", post.District || "");
                    frm.set_value("state", post.State || "");

                } else {

                    frappe.msgprint(
                        __("Invalid or unavailable PIN Code: {0}", [pincode])
                    );

                    frm.set_value("city", "");
                    frm.set_value("state", "");
                }

            })
            .catch(error => {

                console.error(error);

                frappe.msgprint(
                    __("Unable to fetch location for this PIN Code.")
                );
            });
    }

