// =========================================
// HELPERS
// =========================================
function get_available_sizes(frm) {
    const items_table_fieldname = "brick_report_items"; 
    let sizes = [];
    
    if (frm.doc[items_table_fieldname] && frm.doc[items_table_fieldname].length > 0) {
        frm.doc[items_table_fieldname].forEach(row => {
            if (row.size && row.size.trim() !== "" && !sizes.includes(row.size.trim())) {
                sizes.push(row.size.trim());
            }
        });
    }
    return sizes;
}

function refresh_size_dropdowns(frm) {
    const available_sizes = get_available_sizes(frm);
    const field = frm.get_field("test_observation_html");
    if (!field) return;

    field.$wrapper.find(".inline-observation").each(function () {
        const row = $(this);
        const select = row.find(".observation-size");
        const current_val = select.val();

        let size_options = `<option value="">Select Size</option>`;
        available_sizes.forEach(size => {
            const is_selected = (current_val === size) ? "selected" : "";
            size_options += `<option value="${size}" ${is_selected}>${size}</option>`;
        });

        select.html(size_options);
    });
}

function get_defaults_for_test_type(test_type) {
    let defaults = { unit: "", value: "" };
    
    if (test_type === "Weight of brick") defaults.unit = "kgs";
    else if (test_type === "Compressive Strength (N/mm2)") defaults.unit = "N/mm2";
    else if (test_type === "Dry Density(kg/m3)") defaults.unit = "kg/m3";
    else if (test_type === "Water Absorption test") defaults.unit = "%";
    else if (test_type === "Environmental condition") defaults.value = "Ambient";
    
    return defaults;
}

// =========================================
// INSTANT SYNC ENGINE
// =========================================
function sync_tests_with_sizes(frm) {
    let available_sizes = get_available_sizes(frm);
    let tests = frm.doc.test_observations || [];
    let has_changes = false;

    tests.forEach(row => {
        if (!row.test_type) return;

        let data = { observations: [] };
        try { data = JSON.parse(row.test_data); } catch (e) {}

        let current_obs = data.observations || [];
        let new_obs = [];
        const defaults = get_defaults_for_test_type(row.test_type);

        let existing_sizes = [...new Set(current_obs.map(o => o.size).filter(s => s !== ""))];
        let sizes_to_check = available_sizes.length > 0 ? available_sizes : [""];
        
        current_obs.forEach(obs => {
            if (sizes_to_check.includes(obs.size)) {
                new_obs.push(obs); 
            } else if (obs.size === "") {
                let is_untouched = (!obs.value || obs.value === "Ambient" || obs.value === ""); 
                if (available_sizes.length > 0 && is_untouched) {
                    has_changes = true; 
                } else {
                    new_obs.push(obs); 
                }
            } else {
                has_changes = true; 
            }
        });

        sizes_to_check.forEach(size => {
            if (size !== "" && !existing_sizes.includes(size)) {
                has_changes = true;
                if (row.test_type === "Compressive Strength (N/mm2)") {
                    new_obs.push({ size: size, description: " ", value: "", unit: defaults.unit });
                    // Only add Test 2 and Test 3 if it's NOT AAC BLOCKS
                    if (frm.doc.item_group !== "AAC BLOCKS") {
                        new_obs.push({ size: size, description: "Test 1", value: "", unit: defaults.unit });
                        new_obs.push({ size: size, description: "Test 2", value: "", unit: defaults.unit });
                        new_obs.push({ size: size, description: "Test 3", value: "", unit: defaults.unit });
                    }
                }
                else if (row.test_type === "Environmental condition") {
                    new_obs.push({ size: size, description: "Temperature", value: "Ambient", unit: "" });
                    new_obs.push({ size: size, description: "Humidity", value: "Ambient", unit: "" });
                }
                else {
                    new_obs.push({ size: size, description: "", value: defaults.value, unit: defaults.unit });
                }
            } else if (size === "" && existing_sizes.length === 0 && new_obs.length === 0) {
                has_changes = true;
                if (row.test_type === "Compressive Strength (N/mm2)") {
                    new_obs.push({ size: "", description: " ", value: "", unit: defaults.unit });
                    if (frm.doc.item_group !== "AAC BLOCKS") {
                        new_obs.push({ size: "", description: "Test 1", value: "", unit: defaults.unit });
                        new_obs.push({ size: "", description: "Test 2", value: "", unit: defaults.unit });
                        new_obs.push({ size: "", description: "Test 3", value: "", unit: defaults.unit });
                    }
                }
                else if (row.test_type === "Environmental condition") {
                    new_obs.push({ size: "", description: "Temperature", value: "Ambient", unit: "" });
                    new_obs.push({ size: "", description: "Humidity", value: "Ambient", unit: "" });
                }
                else {
                    new_obs.push({ size: "", description: "", value: defaults.value, unit: defaults.unit });
                }
            }
        });

        if (has_changes) {
            row.test_data = JSON.stringify({ observations: new_obs });
        }
    });

    if (has_changes) {
        frm.refresh_field("test_observations");
        render_test_observations(frm);
        frm.dirty();
    } else {
        refresh_size_dropdowns(frm);
    }
}

// =========================================
// DYNAMIC TEST GENERATION
// =========================================
function reset_tests_for_item_group(frm) {
    frm.clear_table("test_observations");
    
    const available_sizes = get_available_sizes(frm);
    const sizes_to_use = available_sizes.length > 0 ? available_sizes : [""];

    const templates = {
        "AAC BLOCKS": ["Dry Density(kg/m3)", "Compressive Strength (N/mm2)", "Water Absorption test", "Environmental condition"],
        "SOLID BLOCKS": ["Weight of brick", "Compressive Strength (N/mm2)"]
    };

    const template = templates[frm.doc.item_group];

    if (template) {
        template.forEach(test_type => {
            const row = frm.add_child("test_observations");
            row.test_type = test_type;
            
            let obs_list = [];
            const defaults = get_defaults_for_test_type(test_type);

            sizes_to_use.forEach(size => {
                if (test_type === "Compressive Strength (N/mm2)") {
                    obs_list.push({ size: size, description: " ", value: "", unit: defaults.unit });
                    // Only add Test 2 and Test 3 if it's NOT AAC BLOCKS
                    if (frm.doc.item_group !== "AAC BLOCKS") {
                        obs_list.push({ size: size, description: "Test 1", value: "", unit: defaults.unit });
                        obs_list.push({ size: size, description: "Test 2", value: "", unit: defaults.unit });
                        obs_list.push({ size: size, description: "Test 3", value: "", unit: defaults.unit });
                    }
                }
                else if (test_type === "Environmental condition") {
                    obs_list.push({ size: size, description: "Temperature", value: "Ambient", unit: "" });
                    obs_list.push({ size: size, description: "Humidity", value: "Ambient", unit: "" });
                }
                else {
                    obs_list.push({ size: size, description: "", value: defaults.value, unit: defaults.unit });
                }
            });

            row.test_data = JSON.stringify({ observations: obs_list });
        });
    }

    frm.refresh_field("test_observations");
    render_test_observations(frm);
    frm.dirty();
}

function render_test_observations(frm) {
    const field = frm.get_field("test_observation_html");
    if (!field) return;

    const wrapper = field.$wrapper;

    wrapper.html(`
        <div class="brick-test-observations">
            <div class="test-observations-title-section">
                <div class="test-observations-title">Test Observations</div>
                <div class="test-observations-help">Add the tests performed and their observations. Select the size applicable.</div>
            </div>
            <div class="test-observations-table">
                <div class="test-table-header">
                    <div class="col-no">No.</div>
                    <div class="col-type">Test Type</div>
                    <div class="col-observation">Observation Details</div>
                    <div class="col-action"></div>
                </div>
                <div class="test-table-body"></div>
            </div>
            <div class="test-add-row-wrapper">
                <button type="button" class="btn btn-primary btn-sm add-test">
                    <i class="fa fa-plus"></i> Add Test
                </button>
            </div>
        </div>
    `);

    const body = wrapper.find(".test-table-body");
    const tests = frm.doc.test_observations || [];

    tests.forEach((row, index) => {
        render_test_row(frm, body, row, index);
    });

    wrapper.find(".add-test").on("click", function () {
        const row = frm.add_child("test_observations");
        row.test_type = "";
        row.test_data = JSON.stringify({ observations: [] });
        frm.refresh_field("test_observations");
        render_test_observations(frm);
        frm.dirty();
    });
}

function render_test_row(frm, container, row, index) {
    let observations = [];

    if (row.test_data) {
        try { observations = JSON.parse(row.test_data).observations || []; } catch (e) {}
    }

    const table_row = $(`
        <div class="test-table-row" data-row-name="${row.name}">
            <div class="col-no test-number">${index + 1}</div>
            <div class="col-type">
                <select class="form-control test-type">
                    <option value="">Select Test Type</option>
                    <option value="Weight of brick" ${row.test_type === "Weight of brick" ? "selected" : ""}>Weight of brick</option>
                    <option value="Compressive Strength (N/mm2)" ${row.test_type === "Compressive Strength (N/mm2)" ? "selected" : ""}>Compressive Strength (N/mm2)</option>
                    <option value="Dry Density(kg/m3)" ${row.test_type === "Dry Density(kg/m3)" ? "selected" : ""}>Dry Density(kg/m3)</option>
                    <option value="Water Absorption test" ${row.test_type === "Water Absorption test" ? "selected" : ""}>Water Absorption test</option>
                    <option value="Environmental condition" ${row.test_type === "Environmental condition" ? "selected" : ""}>Environmental condition</option>
                </select>
            </div>
            <div class="col-observation">
                <div class="observation-lines"></div>
                <button type="button" class="btn btn-xs btn-secondary add-observation">
                    <i class="fa fa-plus"></i> Add Observation
                </button>
            </div>
            <div class="col-action">
                <button type="button" class="btn btn-xs btn-danger remove-test" title="Remove Test">
                    <i class="fa fa-trash"></i>
                </button>
            </div>
        </div>
    `);

    container.append(table_row);

    const observation_lines = table_row.find(".observation-lines");

    observations.forEach(obs => {
        render_inline_observation(frm, row, observation_lines, obs);
    });

    table_row.find(".test-type").on("change", function () {
        row.test_type = $(this).val();
        
        let available_sizes = get_available_sizes(frm);
        let sizes_to_use = available_sizes.length > 0 ? available_sizes : [""];
        
        let new_observations = [];
        const defaults = get_defaults_for_test_type(row.test_type);
        
        sizes_to_use.forEach(size => {
            if (row.test_type === "Compressive Strength (N/mm2)") {
                new_observations.push({ size: size, description: " ", value: "", unit: defaults.unit });
                // Only add Test 2 and Test 3 if it's NOT AAC BLOCKS
                if (frm.doc.item_group !== "AAC BLOCKS") {
                    new_observations.push({ size: size, description: "Test 1", value: "", unit: defaults.unit });
                    new_observations.push({ size: size, description: "Test 2", value: "", unit: defaults.unit });
                    new_observations.push({ size: size, description: "Test 3", value: "", unit: defaults.unit });
                }
            }
            else if (row.test_type === "Environmental condition") {
                new_observations.push({ size: size, description: "Temperature", value: "Ambient", unit: "" });
                new_observations.push({ size: size, description: "Humidity", value: "Ambient", unit: "" });
            }
            else {
                new_observations.push({ size: size, description: "", value: defaults.value, unit: defaults.unit });
            }
        });
        
        row.test_data = JSON.stringify({ observations: new_observations });
        frm.dirty();
        render_test_observations(frm);
    });

    table_row.find(".add-observation").on("click", function () {
        const defaults = get_defaults_for_test_type(row.test_type);
        render_inline_observation(frm, row, observation_lines, {
            size: "", description: "", value: defaults.value, unit: defaults.unit
        });
        save_inline_observations(frm, row, observation_lines);
    });

    table_row.find(".remove-test").on("click", function () {
        frappe.confirm("Remove this test?", function () {
            frm.doc.test_observations = frm.doc.test_observations.filter(t => t.name !== row.name);
            frm.refresh_field("test_observations");
            render_test_observations(frm);
            frm.dirty();
        });
    });
}

function render_inline_observation(frm, test_row, container, observation) {
    const available_sizes = get_available_sizes(frm);
    let size_options = `<option value="">Select Size</option>`;
    
    available_sizes.forEach(size => {
        const is_selected = (observation.size === size) ? "selected" : "";
        size_options += `<option value="${size}" ${is_selected}>${size}</option>`;
    });

    const defaults = get_defaults_for_test_type(test_row.test_type);
    const is_env = (test_row.test_type === "Environmental condition");
    
    const is_desc_readonly = is_env ? "readonly" : "";
    const is_value_readonly = is_env ? "readonly" : "";
    const is_unit_readonly = defaults.unit ? "readonly" : "";

    const observation_row = $(`
        <div class="inline-observation">
            <select class="observation-size">${size_options}</select>
            <input type="text" class="observation-description" placeholder="Description" ${is_desc_readonly}>
            <input type="text" class="observation-value" placeholder="Value" ${is_value_readonly}>
            <input type="text" class="observation-unit" placeholder="Unit" ${is_unit_readonly}>
            <button type="button" class="remove-observation" title="Remove Observation">
                <i class="fa fa-trash"></i>
            </button>
        </div>
    `);

    observation_row.find(".observation-description").val(observation.description || "");
    observation_row.find(".observation-value").val(observation.value || "");
    observation_row.find(".observation-unit").val(observation.unit || "");

    container.append(observation_row);

    observation_row.find("input, select").on("input change", function () {
        save_inline_observations(frm, test_row, container);
    });

    observation_row.find(".observation-size").on("change", function () {
        const selected_size = $(this).val();
        if (!selected_size) return;
        
        let current_desc = observation_row.find(".observation-description").val();
        
        if (test_row.test_type === "Compressive Strength (N/mm2)" && (!current_desc || current_desc === "Test 1")) {
            let count = 0;
            container.find('.inline-observation').each(function() {
                if ($(this).find('.observation-size').val() === selected_size) count++;
            });
            
            if (count <= 1) { 
                observation_row.find(".observation-description").val(" ");
                
                // Only spawn Test 2 and Test 3 if it's NOT AAC BLOCKS
                if (frm.doc.item_group !== "AAC BLOCKS") {
                    render_inline_observation(frm, test_row, container, { size: selected_size, description: "Test 1", value: "", unit: "N/mm2" });
                    render_inline_observation(frm, test_row, container, { size: selected_size, description: "Test 2", value: "", unit: "N/mm2" });
                    render_inline_observation(frm, test_row, container, { size: selected_size, description: "Test 3", value: "", unit: "N/mm2" });
                }
                
                save_inline_observations(frm, test_row, container);
            }
        }
        else if (test_row.test_type === "Environmental condition" && (!current_desc || current_desc === "Temperature")) {
            let count = 0;
            container.find('.inline-observation').each(function() {
                if ($(this).find('.observation-size').val() === selected_size) count++;
            });
            
            if (count <= 1) {
                observation_row.find(".observation-description").val("Temperature");
                observation_row.find(".observation-value").val("Ambient");
                render_inline_observation(frm, test_row, container, { size: selected_size, description: "Humidity", value: "Ambient", unit: "" });
                save_inline_observations(frm, test_row, container);
            }
        }
    });

    observation_row.find(".remove-observation").on("click", function () {
        observation_row.remove();
        save_inline_observations(frm, test_row, container);
    });
}

function save_inline_observations(frm, test_row, container) {
    const observations = [];

    container.find(".inline-observation").each(function () {
        const row = $(this);
        observations.push({
            size: row.find(".observation-size").val(),
            description: row.find(".observation-description").val(),
            value: row.find(".observation-value").val(),
            unit: row.find(".observation-unit").val()
        });
    });

    test_row.test_data = JSON.stringify({ observations: observations });
    frm.dirty();
}

