    const rows =
        frm.doc.brick_report_items || [];


    rows.forEach((row, index) => {

        render_brick_item_row(
            frm,
            body,
            row,
            index
        );

    });


    /* -----------------------------------------------------
       Add Row button
       ----------------------------------------------------- */

    wrapper.find(".add-brick-item").on(
        "click",
        function () {

            add_brick_item(frm);

        }
    );

}


/* =========================================================
   ADD NEW BRICK ROW

   IMPORTANT:
   We DO NOT call render_brick_report_items() here.

   Only the newly-created row is added to the HTML.
   ========================================================= */

function add_brick_item(frm) {

    /* -----------------------------------------------------
       Create child row
       ----------------------------------------------------- */

    const row =
        frm.add_child("brick_report_items");


    /* -----------------------------------------------------
       Initialize values
       ----------------------------------------------------- */

    row.size = "";

    row.manufacturing_date = "";

    row.sales_invoice_no = "";

    row.sales_invoice_date = "";


    /* -----------------------------------------------------
       Refresh hidden child table internally
       ----------------------------------------------------- */

    frm.refresh_field("brick_report_items");


    /* -----------------------------------------------------
       Find HTML table body
       ----------------------------------------------------- */

    const field =
        frm.get_field("brick_report_items_html");


    if (!field) {
        return;
    }


    const body =
        field.$wrapper.find(
            ".brick-items-body"
        );


    /* -----------------------------------------------------
       New row index
       ----------------------------------------------------- */

    const index =
        frm.doc.brick_report_items.length - 1;


    /* -----------------------------------------------------
       Render ONLY the new row
       ----------------------------------------------------- */

    render_brick_item_row(
        frm,
        body,
        row,
        index
    );


    frm.dirty();

}


/* =========================================================
   RENDER ONE BRICK ROW
   ========================================================= */

function render_brick_item_row(
    frm,
    container,
    row,
    index
) {

    /* -----------------------------------------------------
       Create row HTML
       ----------------------------------------------------- */

    const table_row = $(`
    
        <div
            class="brick-items-row"
            data-row-name="${row.name}">


            <!-- =========================================
                 NUMBER
                 ========================================= -->

            <div class="brick-col-no brick-row-number">

                ${index + 1}

            </div>


            <!-- =========================================
                 SIZE
                 ========================================= -->

            <div class="brick-col-size">

                <div class="size-control"></div>

            </div>


            <!-- =========================================
                 MANUFACTURING DATE
                 ========================================= -->

            <div class="brick-col-mfg">

                <input
                    type="date"
                    class="form-control manufacturing-date"
                    value="${row.manufacturing_date || ""}">

            </div>


            <!-- =========================================
                 SALES INVOICE
                 ========================================= -->

            <div class="brick-col-invoice">

                <div class="invoice-control"></div>

            </div>


            <!-- =========================================
                 INVOICE DATE
                 ========================================= -->

            <div class="brick-col-invoice-date">

                <input
                    type="date"
                    class="form-control invoice-date"
                    value="${row.sales_invoice_date || ""}"
                    readonly>

            </div>


            <!-- =========================================
                 DELETE
                 ========================================= -->

            <div class="brick-col-action">

                <button
                    type="button"
                    class="btn btn-xs btn-danger remove-brick-item"
                    title="Remove">

                    <i class="fa fa-trash"></i>

                </button>

            </div>


        </div>

    `);


    /* -----------------------------------------------------
       Add row to HTML table
       ----------------------------------------------------- */

    container.append(table_row);


    /* =====================================================
       SIZE LINK CONTROL
       ===================================================== */

    const size_control =
        frappe.ui.form.make_control({

            df: {

                fieldtype: "Link",

                options: "Item",

                placeholder: "Select Item"

            },

            parent:
                table_row.find(
                    ".size-control"
                ),

            render_input: true

        });


    /* -----------------------------------------------------
       Set existing value
       ----------------------------------------------------- */

    size_control.set_value(
        row.size || ""
    );


    size_control.refresh();


    /* -----------------------------------------------------
       Size change
       ----------------------------------------------------- */

    size_control.$input.on(
        "change",
        function () {

            const value =
                $(this).val();


            frappe.model.set_value(
                row.doctype,
                row.name,
                "size",
                value
            );


            frm.dirty();

        }
    );


    /* =====================================================
       MANUFACTURING DATE
       ===================================================== */

    table_row
        .find(".manufacturing-date")
        .on(
            "change",
            function () {

                const value =
                    $(this).val();


                frappe.model.set_value(
                    row.doctype,
                    row.name,
                    "manufacturing_date",
                    value
                );


                frm.dirty();

            }
        );


    /* =====================================================
       SALES INVOICE LINK CONTROL
       ===================================================== */

    const invoice_control =
        frappe.ui.form.make_control({

            df: {

                fieldtype: "Link",

                options: "Sales Invoice",

                placeholder: "Select Invoice"

            },

            parent:
                table_row.find(
                    ".invoice-control"
                ),

            render_input: true

        });


    /* -----------------------------------------------------
       Set existing invoice
       ----------------------------------------------------- */

    invoice_control.set_value(
        row.sales_invoice_no || ""
    );


    invoice_control.refresh();


    /* =====================================================
       SALES INVOICE CHANGE
       ===================================================== */

    invoice_control.$input.on(
        "change",
        function () {

            const value =
                $(this).val();


            /* ---------------------------------------------
               Save invoice number
               --------------------------------------------- */

            frappe.model.set_value(
                row.doctype,
                row.name,
                "sales_invoice_no",
                value
            );


            frm.dirty();


            /* ---------------------------------------------
               If invoice cleared
               --------------------------------------------- */

            if (!value) {

                frappe.model.set_value(
                    row.doctype,
                    row.name,
                    "sales_invoice_date",
                    ""
                );


                table_row
                    .find(".invoice-date")
                    .val("");


                frm.dirty();

                return;

            }


            /* ---------------------------------------------
               Fetch Posting Date
               --------------------------------------------- */

            frappe.db.get_value(
                "Sales Invoice",
                value,
                "posting_date"
            ).then(function (r) {

                if (
                    r &&
                    r.message &&
                    r.message.posting_date
                ) {

                    const posting_date =
                        r.message.posting_date;


                    /* ---------------------------------
                       Save to child table
                       --------------------------------- */

                    frappe.model.set_value(
                        row.doctype,
                        row.name,
                        "sales_invoice_date",
                        posting_date
                    );


                    /* ---------------------------------
                       Update visible date
                       --------------------------------- */

                    table_row
                        .find(".invoice-date")
                        .val(posting_date);


                    frm.dirty();

                }

            });

        }
    );


    /* =====================================================
       REMOVE ROW
       ===================================================== */

    table_row
        .find(".remove-brick-item")
        .on(
            "click",
            function () {

                frappe.confirm(
                    "Remove this brick detail?",
                    function () {

                        /* ---------------------------------
                           Remove child document properly
                           --------------------------------- */

                        frappe.model.clear_doc(
                            row.doctype,
                            row.name
                        );


                        /* ---------------------------------
                           Remove ONLY HTML row
                           --------------------------------- */

                        table_row.remove();


                        /* ---------------------------------
                           Renumber rows
                           --------------------------------- */

                        renumber_brick_items(frm);


                        /* ---------------------------------
                           Refresh hidden child table
                           --------------------------------- */

                        frm.refresh_field(
                            "brick_report_items"
                        );


                        frm.dirty();

                    }
                );

            }
        );

}


/* =========================================================
   RENUMBER ROWS
   ========================================================= */

function renumber_brick_items(frm) {

    const field =
        frm.get_field(
            "brick_report_items_html"
        );


    if (!field) {
        return;
    }


    field.$wrapper
        .find(".brick-items-row")
        .each(
            function (index) {

                $(this)
                    .find(".brick-row-number")
                    .text(index + 1);

            }
        );

}


