frappe.ui.form.on("Brick Test Report", {
    sales_invoice: function(frm) {

        if (!frm.doc.sales_invoice) {
            frm.clear_table("brick_report_items");
            frm.refresh_field("brick_report_items");
            return;
        }

        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Sales Invoice",
                name: frm.doc.sales_invoice
            },
            callback: function(r) {

                if (r.message) {

                    // Clear existing child rows
                    frm.clear_table("brick_report_items");

                    // Get all items from Sales Invoice
                    (r.message.items || []).forEach(function(item) {

                        let row = frm.add_child("brick_report_items");

                        // Sales Invoice Item → Brick Report Items
                        row.size = item.item_code;
                        row.material = item.item_group;

                    });

                    frm.refresh_field("brick_report_items");
                }
            }
        });
    }
});

frappe.ui.form.on("Brick Test Report", {

    sales_invoice: function(frm) {

        if (!frm.doc.sales_invoice) {
            frm.clear_table("brick_report_items");
            frm.refresh_field("brick_report_items");

            frm.set_value("customer_address", "");
            return;
        }

        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Sales Invoice",
                name: frm.doc.sales_invoice
            },
            callback: function(r) {

                if (r.message) {

                    // =========================
                    // Fill Brick Report Items
                    // =========================
                    frm.clear_table("brick_report_items");

                    (r.message.items || []).forEach(function(item) {

                        let row = frm.add_child("brick_report_items");

                        // Item Code → Size
                        row.size = item.item_code;

                        // Item Group → Material
                        row.material = item.item_group;
                    });

                    frm.refresh_field("brick_report_items");

                    // =========================
                    // Set Customer Address
                    // =========================
                    set_customer_address(frm, r.message);
                }
            }
        });
    },


    address_type: function(frm) {

        if (!frm.doc.sales_invoice) {
            frm.set_value("customer_address", "");
            return;
        }

        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Sales Invoice",
                name: frm.doc.sales_invoice
            },
            callback: function(r) {
                if (r.message) {
                    set_customer_address(frm, r.message);
                }
            }
        });
    }

});


// Common function to set address
function set_customer_address(frm, invoice) {

    if (frm.doc.address_type === "Billing Address") {

        frm.set_value(
            "customer_address",
            invoice.address_display || ""
        );

    } else if (frm.doc.address_type === "Shipping Address") {

        frm.set_value(
            "customer_address",
            invoice.shipping_address || ""
        );

    } else {

        frm.set_value("customer_address", "");
    }
}

frappe.ui.form.on("Purchase Receipt", {

    custom_weight_with_load: function(frm) {
        calculate_weight_difference(frm);
    },

    custom_weight_without_load: function(frm) {
        calculate_weight_difference(frm);
    }

});

function calculate_weight_difference(frm) {

    let with_load = flt(frm.doc.custom_weight_with_load);
    let without_load = flt(frm.doc.custom_weight_without_load);

    let difference = with_load - without_load;

    if (difference < 0) {
        difference = 0;
    }

    frm.set_value("custom_weight_difference", difference);
}

frappe.ui.form.on("Brick Test Report", {

    test_report_based_on: function(frm) {

        // Clear Sales Invoice
        frm.set_value("sales_invoice", "");

        // Clear Sales Invoice related fields
        frm.set_value("sales_invoice_date", "");
        frm.set_value("customer", "");
        frm.set_value("customer_address", "");

        // Clear address type
        frm.set_value("address_type", "");

        // Clear Brick Report Items
        frm.clear_table("brick_report_items");
        frm.refresh_field("brick_report_items");
    },


    sales_invoice: function(frm) {

        if (frm.doc.test_report_based_on !== "Sales Invoice") {
            return;
        }

        if (!frm.doc.sales_invoice) {

            frm.set_value("sales_invoice_date", "");
            frm.set_value("customer", "");
            frm.set_value("customer_address", "");

            frm.clear_table("brick_report_items");
            frm.refresh_field("brick_report_items");

            return;
        }

        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Sales Invoice",
                name: frm.doc.sales_invoice
            },
            callback: function(r) {

                if (!r.message) {
                    return;
                }

                let invoice = r.message;

                // Customer
                frm.set_value("customer", invoice.customer || "");

                // Sales Invoice Date
                frm.set_value(
                    "sales_invoice_date",
                    invoice.posting_date || ""
                );

                // Clear existing child rows
                frm.clear_table("brick_report_items");

