function get_general_customer_address(frm) {

    let address_type = "";

    if (frm.doc.address_type === "Billing Address") {
        address_type = "Billing";
    }
    else if (frm.doc.address_type === "Shipping Address") {
        address_type = "Shipping";
    }
    else {
        console.log("Invalid address type:", frm.doc.address_type);
        return;
    }

    console.log("Searching address...");
    console.log("Customer:", frm.doc.customer);
    console.log("Address Type:", address_type);


    // Get Address records of the selected type
    frappe.db.get_list("Address", {
        filters: {
            address_type: address_type
        },
        fields: [
            "name",
            "address_type"
        ],
        limit: 100
    }).then(function(addresses) {

        console.log("Addresses found:", addresses);

        if (!addresses || !addresses.length) {

            console.log("No addresses found");

            frm.set_value("customer_address", "");
            return;
        }


        // Check each Address
        check_address_for_customer(
            frm,
            addresses,
            0
        );

    }).catch(function(error) {

        console.error("Address list error:", error);

        frm.set_value("customer_address", "");
    });
}


function check_address_for_customer(frm, addresses, index) {

    if (index >= addresses.length) {

        console.log("No matching address found");

        frm.set_value("customer_address", "");
        return;
    }


    let address_name = addresses[index].name;

    console.log(
        "Checking Address:",
        address_name
    );


    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Address",
            name: address_name
        },

        callback: function(r) {

            if (!r.message) {

                check_address_for_customer(
                    frm,
                    addresses,
                    index + 1
                );

                return;
            }


            let address = r.message;

            console.log(
                "Address links:",
                address.links
            );


            // Check whether this Address belongs
            // to the selected Customer
            let belongs_to_customer = false;

            (address.links || []).forEach(function(link) {

                if (
                    link.link_doctype === "Customer" &&
                    link.link_name === frm.doc.customer
                ) {

                    belongs_to_customer = true;
                }

            });


            if (!belongs_to_customer) {

                check_address_for_customer(
                    frm,
                    addresses,
                    index + 1
                );

                return;
            }


            console.log(
                "Matching Address Found:",
                address_name
            );


            // Generate formatted address
            frappe.call({
                method: "frappe.contacts.doctype.address.address.get_address_display",
                args: {
                    address_dict: address_name
                },

                callback: function(display_response) {

                    console.log(
                        "Formatted Address:",
                        display_response.message
                    );


                    frm.set_value(
                        "customer_address",
                        display_response.message || ""
                    );

                }
            });

        }
    });
}

