function calculate_weights(frm) {
    let billing_qty = flt(frm.doc.custom_billing_quantity);
    let with_load = flt(frm.doc.custom_weight_with_load);
    let without_load = flt(frm.doc.custom_weight_without_load);

    // 1. Calculate custom_weight_after_calculation
    let weight_after_calc = with_load - without_load;
    if (weight_after_calc < 0) {
        weight_after_calc = 0;
    }
    frm.set_value("custom_weight_after_calculation", weight_after_calc);

    // 2. Calculate custom_weight_difference (Billing Quantity - Weight After Calculation)
    let weight_diff = billing_qty - weight_after_calc;
    frm.set_value("custom_weight_difference", weight_diff);

    // 3. Keep child quantities synced if already set to Accept or Reject
    handle_accept_reject(frm);
}

function handle_accept_reject(frm) {
    if (!frm.doc.custom_accept) return;

    let target_qty = 0;

    if (frm.doc.custom_accept === 'Accept') {
        target_qty = flt(frm.doc.custom_billing_quantity);
    } 
    else if (frm.doc.custom_accept === 'Reject') {
        target_qty = flt(frm.doc.custom_weight_after_calculation);
    }

    update_item_quantities(frm, target_qty);
}

function update_item_quantities(frm, qty_value) {
    if (frm.doc.items && frm.doc.items.length > 0) {
        frm.doc.items.forEach(row => {
            frappe.model.set_value(row.doctype, row.name, 'qty', qty_value);
        });
        frm.refresh_field('items');
    }
}

