function calculate_travelling_time(frm) {
    if (
        !frm.doc.starting_date ||
        !frm.doc.starting_time ||
        !frm.doc.ending_date ||
        !frm.doc.ending_time
    ) {
        frm.set_value("travelling_time", "");
        return;
    }

    // Create starting datetime
    let start_datetime = new Date(
        `${frm.doc.starting_date}T${frm.doc.starting_time}`
    );

    // Create ending datetime
    let end_datetime = new Date(
        `${frm.doc.ending_date}T${frm.doc.ending_time}`
    );

    // Validate dates
    if (end_datetime < start_datetime) {
        frm.set_value("travelling_time", "");
        frappe.msgprint({
            title: __("Invalid Date/Time"),
            message: __("Ending date/time cannot be before starting date/time."),
            indicator: "red"
        });
        return;
    }

    // Difference in minutes
    let difference_minutes = Math.floor(
        (end_datetime - start_datetime) / (1000 * 60)
    );

    let days = Math.floor(difference_minutes / (24 * 60));
    difference_minutes = difference_minutes % (24 * 60);

    let hours = Math.floor(difference_minutes / 60);
    let minutes = difference_minutes % 60;

    let result = [];

    if (days > 0) {
        result.push(`${days} day${days !== 1 ? "s" : ""}`);
    }

    if (hours > 0) {
        result.push(`${hours} hr${hours !== 1 ? "s" : ""}`);
    }

    if (minutes > 0) {
        result.push(`${minutes} min`);
    }

    // If start and end are exactly the same
    if (result.length === 0) {
        result.push("0 min");
    }

    frm.set_value("travelling_time", result.join(" "));
}
