function calculate_status(frm) {

    let starting_fields = [
        frm.doc.starting_odometer_reading,
        frm.doc.starting_date,
        frm.doc.starting_time
    ];

    let ending_fields = [
        frm.doc.ending_odometer_reading,
        frm.doc.ending_date,
        frm.doc.ending_time
    ];

    // Check if ANY ending field is entered
    let any_ending_entered = ending_fields.some(value => {
        return value !== null && value !== undefined && value !== "";
    });

    // Check if ANY starting field is entered
    let any_starting_entered = starting_fields.some(value => {
        return value !== null && value !== undefined && value !== "";
    });

    // Ending field has priority
    if (any_ending_entered) {
        frm.set_value("status", "Delivered");
    }

    // Starting field entered but ending fields are empty
    else if (any_starting_entered) {
        frm.set_value("status", "In Transit");
    }

    // Nothing entered
    else {
        frm.set_value("status", "Scheduled");
    }
}

