    refresh: function(frm) {
        
        if (frm.is_new()) return;

        let wa_svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 448 512" style="width:16px;height:16px;fill:white;"><path d="M380.9 97.1C339 55.1 283.2 32 223.9 32c-122.4 0-222 99.6-222 222 0 39.1 10.2 77.3 29.6 111L0 480l117.7-30.9c32.4 17.7 68.9 27 106.1 27h.1c122.3 0 224.1-99.6 224.1-222 0-59.3-25.2-115-67.1-157zm-157 341.6c-33.2 0-65.7-8.9-94-25.7l-6.7-4-69.8 18.3L72 359.2l-4.4-7c-18.5-29.4-28.2-63.3-28.2-98.2 0-101.7 82.8-184.5 184.6-184.5 49.3 0 95.6 19.2 130.4 54.1 34.8 34.9 56.2 81.2 56.1 130.5 0 101.8-84.9 184.6-186.6 184.6zm101.2-138.2c-5.5-2.8-32.8-16.2-37.9-18-5.1-1.9-8.8-2.8-12.5 2.8-3.7 5.6-14.3 18-17.6 21.8-3.2 3.7-6.5 4.2-12 1.4-32.6-16.3-54-29.1-75.5-66-5.7-9.8 5.7-9.1 16.3-30.3 1.8-3.7 .9-6.9-.5-9.7-1.4-2.8-12.5-30.1-17.1-41.2-4.5-10.8-9.1-9.3-12.5-9.5-3.2-.2-6.9-.2-10.6-.2-3.7 0-9.7 1.4-14.8 6.9-5.1 5.6-19.4 19-19.4 46.3 0 27.3 19.9 53.7 22.6 57.4 2.8 3.7 39.1 59.7 94.8 83.8 35.2 15.2 49 16.5 66.6 13.9 10.7-1.6 32.8-13.4 37.4-26.4 4.6-13 4.6-24.1 3.2-26.4-1.3-2.5-5-3.9-10.5-6.6z"/></svg>`;
        let button_content = `<span style="display:flex;align-items:center;gap:6px;">${wa_svg} Share Documents</span>`;

        let wa_btn = frm.page.add_inner_button(button_content, function() {
            
            let docs_to_share = [];

            if (frm.doc.custom_insurance_document) docs_to_share.push({ name: 'Insurance Document', url: frm.doc.custom_insurance_document });
            if (frm.doc.custom_group_insurance_document) docs_to_share.push({ name: 'Group Insurance Document', url: frm.doc.custom_group_insurance_document });
            if (frm.doc.custom_pollution_document) docs_to_share.push({ name: 'Pollution Document', url: frm.doc.custom_pollution_document });
            if (frm.doc.custom_rc_document) docs_to_share.push({ name: 'RC Document', url: frm.doc.custom_rc_document });
            if (frm.doc.custom_fc_document) docs_to_share.push({ name: 'FC Document', url: frm.doc.custom_fc_document });

            if (frm.doc.custom_road_tax_table && frm.doc.custom_road_tax_table.length > 0) {
                frm.doc.custom_road_tax_table.forEach((row, idx) => {
                    if (row.road_tax_document) docs_to_share.push({ name: `Road Tax Document (Row ${idx + 1})`, url: row.road_tax_document });
                });
            }
            if (frm.doc.custom_permit_table && frm.doc.custom_permit_table.length > 0) {
                frm.doc.custom_permit_table.forEach((row, idx) => {
                    if (row.permit_document) docs_to_share.push({ name: `Permit Document (Row ${idx + 1})`, url: row.permit_document });
                });
            }

            if (docs_to_share.length === 0) {
                frappe.msgprint({ title: __('No Documents'), indicator: 'orange', message: __('There are no documents attached to this vehicle yet.') });
                return;
            }

            let html = `<div style="padding: 10px 0; font-family: sans-serif;">`;
            html += `<p style="margin-bottom:15px; font-weight:600; color:#333;">Select the documents you want to share:</p>`;
            html += `<div style="display:flex; flex-direction:column; gap:8px; margin-bottom: 20px; max-height:300px; overflow-y:auto;">`;

            docs_to_share.forEach(doc => {
                let absolute_url = window.location.origin + doc.url;
                
                let is_private = doc.url.includes('/private/');
                let badge = is_private ? `<span style="color:#d9534f; font-size:11px; font-weight:bold; margin-left:auto;">[PRIVATE]</span>` : '';

                html += `
                <label style="display: flex; align-items: center; background: #f4f5f7; padding: 12px; border-radius: 6px; cursor: pointer; margin:0; transition: background 0.2s;">
                    <input type="checkbox" class="wa-doc-checkbox" value="${absolute_url}" data-name="${doc.name}" data-private="${is_private}" style="margin-right: 12px; cursor: pointer; width: 18px; height: 18px;" checked>
                    <span style="font-size: 14px; font-weight: 500; color:#1f272e;">${doc.name}</span>
                    ${badge}
                </label>`;
            });

            html += `</div>`;
            html += `<div class="form-group" style="background: #eef6ff; padding: 12px; border-radius: 6px; border: 1px solid #cce2ff;">
                <label style="font-size: 13px; font-weight: 600; color:#017bcf;">Note on Native Sharing</label>
                <small style="color: #666; display:block; margin-top:5px;">You will select the WhatsApp contact inside your system's native share menu. All selected files will be bundled automatically.</small>
            </div>`;
            html += `</div>`;

            let d = new frappe.ui.Dialog({
                title: 'Share Vehicle Documents',
                fields: [
                    { fieldname: 'docs_html', fieldtype: 'HTML', options: html }
                ],
                primary_action_label: 'Share Physical Files',
                primary_action: function() {
                    
                    let selected_docs = [];
                    let blocked_by_privacy = false;
                    
                    d.$wrapper.find('.wa-doc-checkbox:checked').each(function() {
                        let url = $(this).val();
                        if ($(this).attr('data-private') === 'true') {
                            blocked_by_privacy = true;
                        }
                        selected_docs.push({ name: $(this).attr('data-name'), url: url });
                    });

                    // THE SAFETY CATCH
                    if (blocked_by_privacy) {
                        frappe.msgprint({ 
                            title: __('Private File Blocked'), 
                            indicator: 'red', 
                            message: __('You have selected a document that was uploaded as <b>Private</b>. Private files cannot be shared.<br><br>Please uncheck the private file.') 
                        });
                        return;
                    }

                    if (selected_docs.length === 0) {
                        frappe.msgprint({ title: __('Required'), indicator: 'red', message: __('Please select at least one document to share.') });
                        return;
                    }

                    d.get_primary_btn().prop('disabled', true).text('Processing Files...');

                    // Map all selected documents into background download promises
                    let file_promises = selected_docs.map(doc => {
                        return fetch(doc.url)
                            .then(response => response.blob())
                            .then(blob => {
                                let ext = doc.url.split('.').pop().split(/\#|\?/)[0];
                                let full_filename = `${doc.name.replace(/[^a-z0-9]/gi, '_')}.${ext}`;
                                return new File([blob], full_filename, { type: blob.type });
                            });
                    });

                    // Wait for ALL files to finish downloading into memory
                    Promise.all(file_promises)
                        .then(files_array => {
                            
                            // Check if the OS supports sharing this array of files
                            if (navigator.canShare && navigator.canShare({ files: files_array })) {
                                
                                // Hand the entire array of files to the OS share menu
                                navigator.share({
                                    title: 'Vehicle Documents',
                                    text: `Here are the requested documents for Vehicle ${frm.doc.name}`,
                                    files: files_array
                                })
                                .then(() => {
                                    d.hide();
                                })
                                .catch((error) => {
                                    console.log('Share canceled or failed', error);
                                    d.get_primary_btn().prop('disabled', false).text('Share Physical Files');
                                });

                            } else {
                                frappe.msgprint({ 
                                    title: __('Not Supported'), 
                                    indicator: 'orange', 
                                    message: __('Your device or browser does not support sharing multiple physical files natively. Please use a modern browser.') 
                                });
                                d.get_primary_btn().prop('disabled', false).text('Share Physical Files');
                            }
                        })
                        .catch(error => {
                            frappe.msgprint({ title: __('Error'), indicator: 'red', message: __('Could not process the files for sharing.') });
                            d.get_primary_btn().prop('disabled', false).text('Share Physical Files');
                        });
                }
            });
            
            d.show();
        });

        wa_btn.removeClass('btn-default');
        let custom_style = 'background-color:#25D366 !important;color:white !important;font-weight:600 !important;border:none !important;border-radius:6px !important;padding:5px 12px !important;';
        let hover_style = 'background-color:#1DA851 !important;color:white !important;font-weight:600 !important;border:none !important;border-radius:6px !important;padding:5px 12px !important;';

        wa_btn.attr('style', custom_style);
        wa_btn.on('mouseenter', function() { $(this).attr('style', hover_style); });
        wa_btn.on('mouseleave', function() { $(this).attr('style', custom_style); });
    }
});

