frappe.ui.form.on('Purchase Order Item', {
    items_add: function(frm, cdt, cdn) {
        let row = frappe.get_doc(cdt, cdn);
        if (!row.schedule_date) {
            // Calculate 1 month from transaction_date (or today if empty)
            let base_date = frm.doc.transaction_date || frappe.datetime.get_today();
            let future_date = frappe.datetime.add_months(base_date, 1);
            
            frappe.model.set_value(cdt, cdn, 'schedule_date', future_date);
        }
    }
});

frappe.ui.form.on('Purchase Order', {
    validate: function(frm) {
        let base_date = frm.doc.transaction_date || frappe.datetime.get_today();
        let future_date = frappe.datetime.add_months(base_date, 1);

        // Automatically populate empty schedule_date rows on save
        (frm.doc.items || []).forEach(row => {
            if (!row.schedule_date) {
                row.schedule_date = future_date;
            }
        });
    }
});

frappe.ui.form.on('Brick Production', {
    validate: function(frm) {
        // Only check when saving a new record
        if (!frm.is_new()) return;

        // Synchronous call to get the latest draft record
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Brick Production',
                filters: { docstatus: 0 },
                fields: ['name'],
                limit_page_length: 1,
                order_by: 'creation desc'
            },
            async: false, // Prevents form freeze by keeping execution in sync
            callback: function(r) {
                if (r.message && r.message.length > 0) {
                    let last_draft_name = r.message[0].name;

                    // Fetch full doc details synchronously
                    frappe.call({
                        method: 'frappe.client.get',
                        args: {
                            doctype: 'Brick Production',
                            name: last_draft_name
                        },
                        async: false,
                        callback: function(res) {
                            if (res.message) {
                                let last_doc = res.message;
                                let incomplete_rows = [];

                                // Adjust table fieldname if different from 'cutting_sizes'
                                let child_table = last_doc.cutting_sizes || last_doc.brick_sizes || [];

                                (child_table).forEach((row, idx) => {
                                    // Check if values are 0, empty, null, or undefined
                                    let missing_produced = !row.no_of_produced_bricks || row.no_of_produced_bricks == 0;
                                    let missing_damage = row.damage === null || row.damage === undefined || row.damage === '';

                                    if (missing_produced || missing_damage) {
                                        incomplete_rows.push(idx + 1);
                                    }
                                });

                                // Stop save action and show error message
                                if (child_table.length === 0 || incomplete_rows.length > 0) {
                                    frappe.validated = false;
                                    frappe.throw({
                                        title: __('Cannot Save New Entry'),
                                        message: `Save blocked! The previous Draft record (<b><a href="/app/brick-production/${last_draft_name}">${last_draft_name}</a></b>) is missing <b>No. of Produced Bricks</b> or <b>Damage</b> values in row(s): ${incomplete_rows.length ? incomplete_rows.join(', ') : 'All rows'}.<br><br>Please complete the draft first and Submit then only we will move to next record.`
                                    });
                                }
                            }
                        }
                    });
                }
            }
        });
    }
});

