function share_vehicle_attachments(frm) {
    // Fetch attached files for this document
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'File',
            filters: {
                attached_to_doctype: 'Vehicle',
                attached_to_name: frm.doc.name
            },
            fields: ['file_name', 'file_url', 'is_private']
        },
        callback: function(r) {
            if (!r.message || r.message.length === 0) {
                frappe.msgprint(__('No documents are attached to this vehicle.'));
                return;
            }

            let fileListHtml = `<p>Select an attached file to copy the link or share:</p><ul style="padding-left: 18px;">`;
            r.message.forEach(file => {
                const fullUrl = window.location.origin + file.file_url;
                fileListHtml += `
                    <li style="margin-bottom: 10px;">
                        <strong>${file.file_name}</strong><br/>
                        <input type="text" value="${fullUrl}" id="link_${file.name}" style="width: 75%; padding: 4px; font-size: 12px;" readonly />
                        <button class="btn btn-xs btn-default" onclick="navigator.clipboard.writeText('${fullUrl}'); frappe.show_alert('Link copied!');">Copy Link</button>
                    </li>`;
            });
            fileListHtml += `</ul>`;

            const d = new frappe.ui.Dialog({
                title: __('Share Attached Documents'),
                fields: [{
                    fieldname: 'file_links',
                    fieldtype: 'HTML',
                    options: fileListHtml
                }],
                primary_action_label: __('Send via Email'),
                primary_action(values) {
                    d.hide();
                    new frappe.views.CommunicationComposer({
                        doc: frm.doc,
                        subject: `Attached Documents - Vehicle: ${frm.doc.license_plate || frm.doc.name}`,
                        recipients: '',
                        attach_files: r.message.map(f => f.name)
                    });
                }
            });
            d.show();
        }
    });
}

