frappe.ui.form.on("Brick Production", {
    refresh: function(frm) {
        render_time_picker_12hr(frm, "start_time", "starting_time", "Start Time");
        render_time_picker_12hr(frm, "end_time", "ending_time", "End Time");
    }
});

function render_time_picker_12hr(frm, time_field, html_field, label) {
    let raw_val = frm.doc[time_field] || ""; // e.g. "14:30:00"
    let h = 12, m = "00", ampm = "AM";

    if (raw_val) {
        let parts = raw_val.split(":");
        let hour24 = parseInt(parts[0]);
        m = parts[1] ? parts[1].substring(0, 2) : "00";
        
        ampm = hour24 >= 12 ? "PM" : "AM";
        h = hour24 % 12;
        h = h ? h : 12; // the hour '0' should be '12'
    }

    // Build HTML with select fields for robust 12-hour handling
    let hour_options = "";
    for (let i = 1; i <= 12; i++) {
        hour_options += `<option value="${i}" ${i === h ? "selected" : ""}>${i}</option>`;
    }

    let minute_options = "";
    for (let i = 0; i < 60; i += 5) { // 5-minute intervals, change to i++ if you want every minute
        let min_str = i < 10 ? "0" + i : i;
        minute_options += `<option value="${min_str}" ${min_str === m ? "selected" : ""}>${min_str}</option>`;
    }

    frm.fields_dict[html_field].$wrapper.html(`
        <label class="control-label">${label} (12-Hour)</label>
        <div style="display: flex; gap: 5px;">
            <select class="form-control time-hour" style="flex: 1;">${hour_options}</select>
            <select class="form-control time-min" style="flex: 1;">${minute_options}</select>
            <select class="form-control time-ampm" style="flex: 1;">
                <option value="AM" ${ampm === "AM" ? "selected" : ""}>AM</option>
                <option value="PM" ${ampm === "PM" ? "selected" : ""}>PM</option>
            </select>
        </div>
    `);

    // Event listener to update Frappe's underlying field in 24-hour format
    let update_value = function() {
        let hour = parseInt(frm.fields_dict[html_field].$wrapper.find(".time-hour").val());
        let minute = frm.fields_dict[html_field].$wrapper.find(".time-min").val();
        let period = frm.fields_dict[html_field].$wrapper.find(".time-ampm").val();

        // Convert to 24-hour format
        if (period === "PM" && hour < 12) hour += 12;
        if (period === "AM" && hour === 12) hour = 0;

        let hour_str = hour < 10 ? "0" + hour : hour;
        let final_time = `${hour_str}:${minute}:00`;

        frm.set_value(time_field, final_time);
    };

    frm.fields_dict[html_field].$wrapper.find("select").on("change", update_value);
}

