// =========================================================
// FETCH ALL ITEMS FROM ITEM GROUP
// =========================================================

async function fetch_all_brick_items(frm) {

    let all_items = [];
    let start = 0;
    let page_size = 100;

    try {

        while (true) {

            let items = await frappe.db.get_list("Item", {

                filters: {
                    item_group: frm.doc.brick_block,
                    disabled: 0
                },

                fields: [
                    "name",
                    "item_group",
                    "stock_uom"
                ],

                order_by: "name asc",

                limit_start: start,
                limit_page_length: page_size
            });


            // Stop if no more items
            if (!items || !items.length) {
                break;
            }


            // Add fetched items
            all_items = all_items.concat(items);


            // If fewer than page size,
            // this is the last batch
            if (items.length < page_size) {
                break;
            }


            // Next batch
            start += page_size;
        }


        // =================================================
        // NO ITEMS FOUND
        // =================================================

        if (!all_items.length) {

            frappe.msgprint(
                __("No Items found for Item Group: {0}", [
                    frm.doc.brick_block
                ])
            );

            return;
        }


        // =================================================
        // ADD ITEMS TO CHILD TABLE
        // =================================================

        for (let item of all_items) {

            // Get GST Item Tax Template
            let tax_template =
                await get_item_tax_template(item.name);


            // Add child row
            let row = frm.add_child("item_details");


            // ---------------------------------------------
            // GOODS
            // ---------------------------------------------

            row.goods = item.item_group;


            // ---------------------------------------------
            // ITEM
            // ---------------------------------------------

            row.item = item.name;


            // ---------------------------------------------
            // DIMENSIONS
            // ---------------------------------------------

            let dimensions =
                extract_dimensions(item.name);


            row.dimesions_in_mm =
                dimensions.mm;

            row.dimesions_in_inch =
                dimensions.inch;


            // ---------------------------------------------
            // UOM
            // ---------------------------------------------

            row.uom = item.stock_uom;


            // ---------------------------------------------
            // GST
            // ---------------------------------------------

            row.gst =
                tax_template || "";


            // ---------------------------------------------
            // PRICE UNIT
            // MANUAL ENTRY
            // ---------------------------------------------

            row.priceunit = 0;


            // ---------------------------------------------
            // COST WITH GST
            // ---------------------------------------------

            row.each_block_cost_with_gst = 0;
        }


        // Refresh child table
        frm.refresh_field("item_details");


        // Success message
        frappe.msgprint(
            __("{0} items fetched successfully.", [
                all_items.length
            ])
        );

    }

    catch (error) {

        console.error(
            "Brick Catalog Item Fetch Error:",
            error
        );

        frappe.msgprint(
            __("Unable to fetch Brick Items.")
        );
    }
}


// =========================================================
// GET ITEM TAX TEMPLATE FROM ITEM MASTER
// =========================================================

async function get_item_tax_template(item_code) {

    try {

        let item =
            await frappe.db.get_doc(
                "Item",
                item_code
            );


        if (
            item &&
            item.taxes &&
            item.taxes.length
        ) {

            // Take first Item Tax row
            let tax_row =
                item.taxes[0];


            return (
                tax_row.item_tax_template || ""
            );
        }


        return "";

    }

    catch (error) {

        console.error(
            "GST Fetch Error:",
            item_code,
            error
        );

        return "";
    }
}


// =========================================================
// EXTRACT DIMENSIONS FROM ITEM CODE
//
// Example:
//
// AAC 600 x 200 x 250
//
// MM:
// 600x200x250
//
// INCH:
// 24x8x10
// =========================================================

function extract_dimensions(item_code) {

    let result = {
        mm: "",
        inch: ""
    };


    if (!item_code) {
        return result;
    }


    // Find three numbers separated by x
    let match = item_code.match(
        /(\d+(?:\.\d+)?)\s*x\s*(\d+(?:\.\d+)?)\s*x\s*(\d+(?:\.\d+)?)/i
    );


    if (!match) {
        return result;
    }


    let mm1 =
        parseFloat(match[1]);

    let mm2 =
        parseFloat(match[2]);

    let mm3 =
        parseFloat(match[3]);


    // =====================================================
    // DIMENSIONS IN MM
    // =====================================================

    result.mm =
        mm1 + "x" +
        mm2 + "x" +
        mm3;


    // =====================================================
    // CONVERT MM TO INCH
    // =====================================================

    let inch1 =
        Math.round(mm1 / 25.4);

    let inch2 =
        Math.round(mm2 / 25.4);

    let inch3 =
        Math.round(mm3 / 25.4);


    result.inch =
        inch1 + "x" +
        inch2 + "x" +
        inch3;


    return result;
}


