// =========================================================
// CALCULATE EACH BLOCK COST WITH GST
// =========================================================

async function calculate_block_cost(
    frm,
    cdt,
    cdn
) {

    let row =
        locals[cdt][cdn];


    let price =
        flt(row.priceunit);


    // =====================================================
    // NO PRICE
    // =====================================================

    if (!price) {

        frappe.model.set_value(
            cdt,
            cdn,
            "each_block_cost_with_gst",
            0
        );

        return;
    }


    // =====================================================
    // NO GST TEMPLATE
    // =====================================================

    if (!row.gst) {

        frappe.model.set_value(
            cdt,
            cdn,
            "each_block_cost_with_gst",
            flt(price, 2)
        );

        return;
    }


    try {

        // Get Item Tax Template
        let template =
            await frappe.db.get_doc(
                "Item Tax Template",
                row.gst
            );


        let gst_rate = 0;


        // =================================================
        // GET TOTAL GST RATE
        // =================================================

        if (
            template &&
            template.taxes &&
            template.taxes.length
        ) {

            for (
                let tax of template.taxes
            ) {

                gst_rate +=
                    flt(tax.tax_rate);
            }
        }


        // =================================================
        // GST CALCULATION
        // =================================================

        let gst_amount =
            price * gst_rate / 100;


        let total =
            price + gst_amount;


        // =================================================
        // SET FINAL COST
        // =================================================

        frappe.model.set_value(
            cdt,
            cdn,
            "each_block_cost_with_gst",
            flt(total, 2)
        );

    }

    catch (error) {

        console.error(
            "GST Calculation Error:",
            error
        );

        // If template cannot be read,
        // keep price as final amount

        frappe.model.set_value(
            cdt,
            cdn,
            "each_block_cost_with_gst",
            flt(price, 2)
        );
    }
}

