                let row = frm.add_child("item_details");

                // Goods
                row.goods = item.item_group;

                // Item
                row.item = item.name;

                // Dimensions
                let dimensions = extract_dimensions(item.name);

                row.dimesions_in_mm = dimensions.mm;
                row.dimesions_in_inch = dimensions.inch;

                // UOM
                row.uom = item.stock_uom;

                // Initially blank
                row.gst = "";

                // Manual price
                row.priceunit = 0;

                // Initial cost
                row.each_block_cost_with_gst = 0;

                // Fetch GST
                get_item_tax_template(
                    item.name,
                    row
                );
            });

            frm.refresh_field("item_details");

            frappe.msgprint(
                __("{0} items fetched successfully.", [
                    items.length
                ])
            );
