// =========================================================
// CALCULATE EACH BLOCK COST WITH GST
// =========================================================

function calculate_block_cost(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    let price = flt(row.priceunit);

    // No price
    if (!price) {

        frappe.model.set_value(
            cdt,
            cdn,
            "each_block_cost_with_gst",
            0
        );

        return;
    }

    // No GST template
    if (!row.gst) {

        frappe.model.set_value(
            cdt,
            cdn,
            "each_block_cost_with_gst",
            flt(price, 2)
        );

        return;
    }

    // Get GST Rate directly from Item Tax Template
    frappe.db.get_value(
        "Item Tax Template",
        row.gst,
        "gst_rate"
    ).then(function(r) {

        let gst_rate = 0;

        if (
            r &&
            r.message &&
            r.message.gst_rate
        ) {
            gst_rate = flt(
                r.message.gst_rate
            );
        }

        // Calculate GST
        let gst_amount =
            price * gst_rate / 100;

        // Price + GST
        let total =
            price + gst_amount;

        // Set final amount
        frappe.model.set_value(
            cdt,
            cdn,
            "each_block_cost_with_gst",
            flt(total, 2)
        );

    }).catch(function(error) {

        console.error(
            "GST Calculation Error:",
            error
        );

        // If GST cannot be fetched,
        // keep price without GST
        frappe.model.set_value(
            cdt,
            cdn,
            "each_block_cost_with_gst",
            flt(price, 2)
        );

    });

}

