function render_dashboard(frm) {
    const html_field = frm.get_field("vehicles");
    if (!html_field) return; 
    
    const wrapper = html_field.$wrapper;
    const selected_vehicle = frm.doc.select_vehicle || "";

    frappe.call({
        url: "/api/method/get_vehicle_space_data",
        type: "GET",
        args: { vehicle: selected_vehicle },
        callback: function(r) {
            const data = r.message || [];

            let html = `
            <div class="vehicle-dashboard-container">
                <div class="vehicle-dashboard-toolbar">
                    <div class="vehicle-dashboard-filter">
                        <label style="margin:0; font-weight:600;">Filter Vehicle:</label>
                        <select id="vehicle-filter-dropdown" class="form-control" style="width: 220px; display:inline-block;">
                            <option value="">-- All Vehicles --</option>
                        </select>
                    </div>
                </div>

                <div style="overflow-x: auto;">
                    <table class="vehicle-dashboard-table">
                        <thead>
                            <tr>
                                <th style="background:#dbeafe; width: 140px;">VEHICLE</th>
                                <th>RC</th>
                                <th>FC</th>
                                <th>PERMIT</th>
                                <th>INSURANCE</th>
                                <th>GROUP INS</th>
                                <th>ROAD TAX</th>
                                <th>POLLUTION</th>
                            </tr>
                        </thead>
                        <tbody>
            `;

            if (data.length === 0) {
                html += `<tr><td colspan="8" style="text-align:center; padding:20px;">No vehicles found.</td></tr>`;
            } else {
                data.forEach(item => {
                    html += `
                    <tr>
                        <td class="v-plate-cell">
                            <div style="font-size: 13px; margin-bottom: 6px;">${escape_html(item.license_plate)}</div>
                            <button class="btn btn-default btn-xs btn-share-single" data-name="${escape_html(item.name)}">
                                🔗 Share Files
                            </button>
                        </td>
                        ${render_td(item.rc)}
                        ${render_td(item.fc)}
                        ${render_td(item.permit)}
                        ${render_td(item.insurance)}
                        ${render_td(item.group_insurance)}
                        ${render_td(item.road_tax)}
                        ${render_td(item.pollution)}
                    </tr>
                    `;
                });
            }

            html += `
                        </tbody>
                    </table>
                </div>
            </div>
            `;

            wrapper.html(html);
            populate_dropdown(frm, selected_vehicle);
            attach_events(wrapper, data);
        }
    });
}

function render_td(cell) {
    if (!cell || (cell.text === "-" && (!cell.files || cell.files.length === 0))) {
        return `<td>-</td>`;
    }
    
    let class_name = "";
    let display_val = cell.text;

    if (cell.expired) {
        class_name = "cell-expired";
        if (cell.text === "-") display_val = "Expired";
    } else if (cell.warning) {
        class_name = "cell-warning";
    }
    
    let file_html = "";
    if (cell.files && cell.files.length > 0) {
        cell.files.forEach(f => {
            const absolute_url = window.location.origin + f.url;
            file_html += `<br><a href="${absolute_url}" target="_blank" class="doc-file-link">📎 ${escape_html(f.label)}</a>`;
        });
    }

    return `<td class="${class_name}">${display_val}${file_html}</td>`;
}

