            (r.message || []).forEach(v => {
                const label = v.license_plate || v.name;
                const is_selected = v.name === selected_val ? "selected" : "";
                select.append(`<option value="${v.name}" ${is_selected}>${label}</option>`);
            });

            select.on("change", function() {
                if (frm.fields_dict.select_vehicle) {
                    frm.set_value("select_vehicle", $(this).val());
                } else {
                    frm.doc.select_vehicle = $(this).val();
                    render_dashboard(frm);
                }
            });
        }
    });
}

function attach_events(wrapper, data) {
    wrapper.find(".btn-share-single").on("click", function() {
        const name = $(this).attr("data-name");
        const info = data.find(v => v.name === name);
        if (!info) return;
        
        open_share_dialog(info);
    });
}

function open_share_dialog(info) {
    let available_files = [];
    const doc_keys = ['rc', 'fc', 'permit', 'insurance', 'group_insurance', 'road_tax', 'pollution'];

    doc_keys.forEach(key => {
        if (info[key] && info[key].files && info[key].files.length > 0) {
            info[key].files.forEach(f => {
                available_files.push({ label: f.label, url: f.url });
            });
        }
    });

    const vehicle_name = info.license_plate || info.name;

    if (available_files.length === 0) {
        frappe.msgprint({ 
            title: "No Documents Found", 
            message: `There are no document files uploaded for vehicle <b>${vehicle_name}</b>.`, 
            indicator: "orange" 
        });
        return;
    }

    let fields = [
        {
            fieldname: "share_channel",
            fieldtype: "Select",
            label: "Share Via Option",
            options: [
                "WhatsApp App / Mobile Share (Sends Actual PDF Files)",
                "WhatsApp Web (Desktop - Sends Links)",
                "Copy Links to Clipboard"
            ],
            default: "WhatsApp App / Mobile Share (Sends Actual PDF Files)"
        },
        { fieldtype: "Section Break" },
        {
            fieldname: "help_text",
            fieldtype: "HTML",
            options: `<div style="padding-bottom: 8px; font-weight: 600; font-size: 13px;">Select Documents to Include:</div>`
        }
    ];

    available_files.forEach(f => {
        let safe_fieldname = f.label.replace(/[^a-zA-Z0-9]/g, '_').toLowerCase();
        fields.push({
            fieldtype: 'Check',
            fieldname: safe_fieldname,
            label: `Attach ${f.label} File`,
            default: 0
        });
    });

    let d = new frappe.ui.Dialog({
        title: `Share Documents - ${vehicle_name}`,
        fields: fields,
        primary_action_label: 'Share Now',
        primary_action(values) {
            let selected_docs = [];
            let selected_files_data = [];
            
            available_files.forEach(f => {
                let safe_fieldname = f.label.replace(/[^a-zA-Z0-9]/g, '_').toLowerCase();
                if (values[safe_fieldname]) {
                    selected_docs.push(`• *${f.label}*: ${window.location.origin}${f.url}`);
                    selected_files_data.push(f);
                }
            });

            if (selected_docs.length === 0) {
                frappe.msgprint("Please select at least one document to share.");
                return;
            }

            let title = `Document for ${vehicle_name}`;
            let text = `*Document for ${vehicle_name}*\n\n` + selected_docs.join('\n\n');
            let share_option = values.share_channel;
            
            d.hide();
            execute_share_method(title, text, selected_files_data, share_option);
        }
    });

    d.show();
}

async function execute_share_method(title, text, selected_files, share_option) {
    // OPTION 1: WhatsApp App / Mobile Share (Sends Actual Files)
    if (share_option.includes("WhatsApp App")) {
        if (navigator.share && navigator.canShare) {
            try {
                frappe.show_alert({message: "Preparing PDF files for sharing...", indicator: "blue"});
                
                let fileObjects = [];
                for (let f of selected_files) {
                    try {
                        const response = await fetch(f.url);
                        const blob = await response.blob();
                        const filename = f.url.split('/').pop().split('?')[0] || (f.label.replace(/[^a-zA-Z0-9]/g, '_') + "_document.pdf");
                        const file = new File([blob], filename, { type: blob.type });
                        fileObjects.push(file);
                    } catch (e) {
                        console.warn("Could not fetch file", f.url);
                    }
                }
                
                if (fileObjects.length > 0 && navigator.canShare({ files: fileObjects })) {
                    await navigator.share({
                        title: title,
                        text: title,
                        files: fileObjects
                    });
                    return;
                }
            } catch (e) {
                console.warn("Direct file share failed or canceled", e);
            }
        }
        
        // Fallback to WhatsApp mobile scheme if file attachment fails
        const encoded_text = encodeURIComponent(text);
        window.open(`https://api.whatsapp.com/send?text=${encoded_text}`, '_blank');
        return;
    }

    // OPTION 2: WhatsApp Web (Desktop - Sends Links)
    if (share_option.includes("WhatsApp Web")) {
        const encoded_text = encodeURIComponent(text);
        window.open(`https://web.whatsapp.com/send?text=${encoded_text}`, '_blank');
        return;
    }

    // OPTION 3: Copy to Clipboard
    if (share_option.includes("Copy Links")) {
        try {
            await navigator.clipboard.writeText(text);
            frappe.show_alert({ message: "Document links copied to clipboard!", indicator: "green" });
        } catch (err) {
            frappe.msgprint("<pre>" + text + "</pre>");
        }
    }
}

function escape_html(str) {
    if (!str) return "";
    return String(str).replace(/[&<>"'`=\/]/g, function (s) {
        return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;", "/": "&#x2F;", "`": "&#x60;", "=": "&#x3D;" }[s];
    });
}


