frappe.ui.form.on('Sales Invoice', {
    vehicle_no(frm) {
        if (frm.doc.vehicle_no) {
            frm.set_value(
                'vehicle_no',
                frm.doc.vehicle_no.toUpperCase()
            );
        }
    }
});

frappe.ui.form.on("Vehicle", {
    custom_valid_upto: function(frm) {
        if (frm.doc.custom_valid_upto) {
            frm.set_value("custom_fc_end_date", frm.doc.custom_valid_upto);
        }
    },

    custom_fc_end_date: function(frm) {
        if (frm.doc.custom_fc_end_date) {
            frm.set_value("custom_valid_upto", frm.doc.custom_fc_end_date);
        }
    }
});

frappe.ui.form.on("Sales Invoice", {
    refresh(frm) {

        // Remove existing custom button if already created
        frm.remove_custom_button("Print Invoice");

        // Add our custom Print Invoice button
        frm.add_custom_button("Print Invoice", function () {

            let formats = [
                "Original For Recipient",
                "Triplecate For Supplier",
                "Duplicate For Transporter"
            ];

            let dialog = new frappe.ui.Dialog({
                title: "Select Print Format",
                fields: [
                    {
                        fieldname: "print_format",
                        fieldtype: "Select",
                        label: "Print Format",
                        options: formats.join("\n"),
                        reqd: 1
                    }
                ],
                primary_action_label: "Print",
                primary_action(values) {

                    if (!values.print_format) {
                        frappe.msgprint("Please select a Print Format");
                        return;
                    }

                    dialog.hide();

                    // Open selected print format
                    let url =
                        "/printview"
                        + "?doctype=" + encodeURIComponent(frm.doc.doctype)
                        + "&name=" + encodeURIComponent(frm.doc.name)
                        + "&format=" + encodeURIComponent(values.print_format)
                        + "&no_letterhead=0";

                    window.open(url, "_blank");
                }
            });

            dialog.show();
        });
    }
});
